mapper.select:
SELECT std.DOCUMENT_ID, std.OLDCASE_SRC_ID, pdoc.STATENO MATCHED_STATENO, pdoc.DISCARD_STATUS, std.FNAME, std.MNAME, std.LNAME, std.SUFFIX, std.DOB_TEXT, std.DATE_OF_BIRTH, std.DOD_TEXT, std.DATE_OF_DEATH, std.SSN, std.MED_RECORD_NUMBER, std.DIN, std.ADDRESS, std.CITY, std.STATE, std.ZIP, std.RACE, std.ETHNICITY, std.CURRENT_GENDER, std.CREATE_DATE, std.CREATE_UID, std.RACE_INDIAN, std.RACE_BLACK, std.RACE_ASIAN, std.RACE_PACIFIC, std.RACE_WHITE, std.RACE_MULTIPLE, std.RACE_OTHER, std.RACE_UNKNOWN, std.COMMENTS
from STD_OLD_CASES_DOC std LEFT OUTER JOIN person_doc_association pdoc
ON (std.document_id = pdoc.document_id AND pdoc.dissassociation_date IS NULL) WHERE std.DOCUMENT_ID = #{documentId}
